/** Priority order used when a card matches tags from more than one category — narrower,
 *  more clearly-defining effects win over broader ones (e.g. a card tagged both "removal" and
 *  "burn" is categorized as Burn, not the more generic Removal). */
export const FUNCTION_CATEGORY_PRIORITY: string[] = [
  'Board Wipe',
  'Counterspells',
  'Tutors',
  'Discard',
  'Recursion',
  'Bounce',
  'Burn',
  'Sac Outlets',
  'Protection',
  'Lifegain',
  'Card Draw',
  'Ramp',
  'Copy Effects',
  'Counters',
  'Removal',
  'Extra Turns',
]
